// src/utils/astro-config.ts
import * as p4 from "@clack/prompts";
import fs3 from "fs-extra";
import semver3 from "semver";
var CONFIG_EXTENSIONS = ["ts", "js", "mjs", "cjs"];
async function findAstroConfig() {
  for (const ext of CONFIG_EXTENSIONS) {
    const configPath = `astro.config.${ext}`;
    if (await fileExists(configPath)) {
      return configPath;
    }
  }
  return null;
}
async function getAstroVersion() {
  try {
    const pkg = await readJsonFile("package.json");
    if (pkg.dependencies?.astro) {
      const astroVersion = pkg.dependencies.astro.replace(/^\^|~/, "");
      return astroVersion;
    }
    p4.log.error(
      highlighter.error(
        "Astro seems not installed in your project, please check your package.json"
      )
    );
    return null;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "An unknown error occurred";
    p4.log.error(highlighter.error(`Failed to check Astro version: ${errorMessage}`));
    return null;
  }
}
async function setupAstroConfig() {
  try {
    let configPath = await findAstroConfig();
    let content = "";
    if (configPath) {
      content = await fs3.readFile(configPath, "utf-8");
    } else {
      configPath = "astro.config.ts";
      content = `import { defineConfig } from "astro/config";

export default defineConfig({});
`;
    }
    if (!content.includes('import tailwindcss from "@tailwindcss/vite"')) {
      content = `import tailwindcss from "@tailwindcss/vite";
${content}`;
    }
    const configStart = content.indexOf("defineConfig(") + "defineConfig(".length;
    const configEnd = content.lastIndexOf(");");
    let config = content.slice(configStart, configEnd);
    config = config.trim().replace(/^{|}$/g, "").trim();
    const astroVersion = await getAstroVersion();
    if (astroVersion && semver3.lt(astroVersion, "5.7.0")) {
      if (!config.includes("experimental")) {
        const needsComma = config.length > 0 && !config.trimEnd().endsWith(",");
        config += (needsComma ? "," : "") + `
	experimental: {
		svg: true,
	},`;
      } else if (!config.includes("svg: true") && !config.includes("svg: {")) {
        const expEnd = config.indexOf("experimental:") + "experimental:".length;
        const blockStart = config.indexOf("{", expEnd) + 1;
        config = config.slice(0, blockStart) + `
		svg: true,` + config.slice(blockStart);
      }
    }
    if (!config.includes("vite:")) {
      const needsComma = config.length > 0 && !config.trimEnd().endsWith(",");
      config += (needsComma ? "," : "") + `
	vite: {
		plugins: [tailwindcss()],
	},`;
    } else if (!config.includes("plugins: [")) {
      const viteEnd = config.indexOf("vite:") + "vite:".length;
      const blockStart = config.indexOf("{", viteEnd) + 1;
      config = config.slice(0, blockStart) + `
		plugins: [tailwindcss()],` + config.slice(blockStart);
    } else if (!config.includes("tailwindcss()")) {
      const pluginsStart = config.indexOf("plugins:") + "plugins:".length;
      const arrayStart = config.indexOf("[", pluginsStart) + 1;
      config = config.slice(0, arrayStart) + `tailwindcss(), ` + config.slice(arrayStart);
    }
    const newContent = `${content.slice(0, configStart)}{
	${config}
}${content.slice(configEnd)}`;
    await fs3.writeFile(configPath, newContent, "utf-8");
    return true;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "An unknown error occurred";
    p4.log.error(highlighter.error(`Failed to setup Astro config: ${errorMessage}`));
    return false;
  }
}

// src/utils/env.ts
import * as p5 from "@clack/prompts";
import fs4 from "fs-extra";
var ENV_LOCAL_PATH = ".env.local";
var GITIGNORE_PATH = ".gitignore";
var STARWIND_ENV_CONTENT = `# Starwind Pro registry setup
STARWIND_LICENSE_KEY=your_starwind_pro_license_key
`;
var DEFAULT_GITIGNORE_CONTENT = `# build output
dist/

# generated types
.astro/

# dependencies
node_modules/

# logs
npm-debug.log*
yarn-debug.log*
yarn-error.log*
pnpm-debug.log*

# environment variables
.env
.env.local
.env.production

# macOS-specific files
.DS_Store

# jetbrains setting folder
.idea/
`;
function hasStarwindLicenseKey(content) {
  return /^STARWIND_LICENSE_KEY\s*=/m.test(content);
}
function hasEnvLocalInGitignore(content) {
  const lines = content.split(/\r?\n/);
  return lines.some((line) => {
    const trimmed = line.trim();
    return trimmed === ".env.local" || trimmed === ".env.local/" || trimmed === ".env*" || trimmed === ".env.*" || trimmed === "*.local";
  });
}
async function setupEnvLocal() {
  try {
    const exists = await fileExists(ENV_LOCAL_PATH);
    if (exists) {
      const content = await fs4.readFile(ENV_LOCAL_PATH, "utf-8");
      if (hasStarwindLicenseKey(content)) {
        return true;
      }
      const newContent = STARWIND_ENV_CONTENT + "\n" + content;
      await fs4.writeFile(ENV_LOCAL_PATH, newContent, "utf-8");
    } else {
      await fs4.writeFile(ENV_LOCAL_PATH, STARWIND_ENV_CONTENT, "utf-8");
    }
    return true;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "An unknown error occurred";
    p5.log.error(highlighter.error(`Failed to setup .env.local: ${errorMessage}`));
    return false;
  }
}
async function setupGitignore() {
  try {
    const exists = await fileExists(GITIGNORE_PATH);
    if (exists) {
      const content = await fs4.readFile(GITIGNORE_PATH, "utf-8");
      if (hasEnvLocalInGitignore(content)) {
        return true;
      }
      const needsNewline = content.length > 0 && !content.endsWith("\n");
      const newContent = content + (needsNewline ? "\n" : "") + ".env.local\n";
      await fs4.writeFile(GITIGNORE_PATH, newContent, "utf-8");
    } else {
      await fs4.writeFile(GITIGNORE_PATH, DEFAULT_GITIGNORE_CONTENT, "utf-8");
    }
    return true;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "An unknown error occurred";
    p5.log.error(highlighter.error(`Failed to setup .gitignore: ${errorMessage}`));
    return false;
  }
}
async function setupStarwindProEnv() {
  const envResult = await setupEnvLocal();
  const gitignoreResult = await setupGitignore();
  return envResult && gitignoreResult;
}
async function checkStarwindProEnv() {
  const envExists = await fileExists(ENV_LOCAL_PATH);
  if (!envExists) return false;
  try {
    const envContent = await fs4.readFile(ENV_LOCAL_PATH, "utf-8");
    if (!hasStarwindLicenseKey(envContent)) return false;
  } catch {
    return false;
  }
  const gitignoreExists = await fileExists(GITIGNORE_PATH);
  if (gitignoreExists) {
    try {
      const gitignoreContent = await fs4.readFile(GITIGNORE_PATH, "utf-8");
      if (!hasEnvLocalInGitignore(gitignoreContent)) return false;
    } catch {
      return false;
    }
  } else {
    return false;
  }
  return true;
}

// src/utils/layout.ts
import * as p6 from "@clack/prompts";
import fs5 from "fs-extra";
var LAYOUT_PATHS = ["src/layouts/Layout.astro", "src/layouts/BaseLayout.astro"];
async function findLayoutFile() {
  for (const layoutPath of LAYOUT_PATHS) {
    if (await fileExists(layoutPath)) {
      return layoutPath;
    }
  }
  return null;
}
function hasCssImport(content, cssPath) {
  const normalizedCssPath = cssPath.replace(/\\/g, "/");
  const importPatterns = [
    // import "@/styles/starwind.css"
    new RegExp(`import\\s+["']${escapeRegExp(normalizedCssPath)}["']`),
    // import "@/styles/starwind.css";
    new RegExp(`import\\s+["']${escapeRegExp(normalizedCssPath)}["'];?`),
    // Handle paths without @/ prefix if cssPath starts with src/
    ...normalizedCssPath.startsWith("src/") ? [new RegExp(`import\\s+["']@/${escapeRegExp(normalizedCssPath.slice(4))}["']`)] : [],
    // Handle @/ paths if cssPath doesn't have it
    ...!normalizedCssPath.startsWith("@/") ? [new RegExp(`import\\s+["']@/${escapeRegExp(normalizedCssPath)}["']`)] : []
  ];
  return importPatterns.some((pattern) => pattern.test(content));
}
function escapeRegExp(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
function toImportPath(cssPath) {
  const normalizedPath = cssPath.replace(/\\/g, "/");
  if (normalizedPath.startsWith("@/")) {
    return normalizedPath;
  }
  if (normalizedPath.startsWith("src/")) {
    return `@/${normalizedPath.slice(4)}`;
  }
  return `@/${normalizedPath}`;
}
function addCssImportToLayout(content, cssPath) {
  const importPath = toImportPath(cssPath);
  const importStatement = `import "${importPath}";`;
  const frontmatterMatch = content.match(/^---\r?\n/);
  if (frontmatterMatch) {
    const insertPosition = frontmatterMatch[0].length;
    return content.slice(0, insertPosition) + importStatement + "\n" + content.slice(insertPosition);
  } else {
    return `---
${importStatement}
---

${content}`;
  }
}
async function setupLayoutCssImport(cssPath) {
  try {
    const layoutPath = await findLayoutFile();
    if (!layoutPath) {
      return true;
    }
    const content = await fs5.readFile(layoutPath, "utf-8");
    if (hasCssImport(content, cssPath)) {
      return true;
    }
    const updatedContent = addCssImportToLayout(content, cssPath);
    await fs5.writeFile(layoutPath, updatedContent, "utf-8");
    return true;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "An unknown error occurred";
    p6.log.error(highlighter.error(`Failed to setup CSS import in layout: ${errorMessage}`));
    return false;
  }
}

